<template>
	<view class="courseDetail">
		<!-- 课程详情 -->
		<view class="item">
			<view class="item-titbox">
				<text class="item-type" :class="info.bg">{{info.subjectName}}</text>
				<!-- <text class="item-type shuxue">数学</text> -->
				<!-- <text class="item-type yuwen">语文</text> -->
				<!-- <text class="item-type wuli">物理</text> -->
				<text class="item-title">{{info.courseTitle}}</text>
			</view>
			<view class="item-time">{{info.desc}}</view>
			<view class="item-address" v-if="info.placeName">
				<text class="iconfont icon-touzijigou"></text>
				<text class="adres-tex">{{info.placeName}}</text>
			</view>
			<view class="item-address" v-if="info.campusAddress">
				<text class="iconfont icon-fenxiangsheding-dizhi"></text>
				<text class="adres-tex ">{{info.campusAddress}}</text>
				<!-- <text class="iconfont icon-right"></text> -->
			</view>
			<div class="item-price">
				<text class="danwei">¥</text><text class="money">{{info.price}}</text> / 剩余<text
					class="num">{{info.remainCount}}</text>讲
			</div>
		</view>

		<!-- 授课老师 -->
		<view class="teacher-box">
			<view class="teacher-title">
				<text></text>授课老师（1）
			</view>
			<view class="teacher-list">
				<view class="teacher-item">
					<view class="teacher-img">
						<image :src="imgurl + info.teacherAvatar" mode="aspectFit"></image>
					</view>
					<view class="teacher-name">{{info.teacherName}}</view>
				</view>
			</view>
		</view>

		<!-- 大纲 -->
		<view class="teacher-box">
			<view class="teacher-title">
				<text></text>大纲<view class="num">/ {{info.scheduleList.length}}次课</view>
			</view>
			<view class="grade-list">
				<view class="grade-item" v-for="item in info.scheduleList" :key="item.scheduleId">
					<text>第{{item.sessionNum}}讲</text>
					<view class="grade-cont">
						<view class="grade-tex">{{item.scheduleTime}}</view>
						<text :class="{active:info.scheduleStatus == 1}">{{info.scheduleStatus == 1 ? '已开课' : '未开课'}}</text>
					</view>
				</view>
			</view>
		</view>

		<!-- 添加选课单 -->
		<view class="add-box" :style="{paddingBottom: paddingbottom + 'rpx'}">
			<view class="shopping-car" @click="to(`/pages/index/grade`)">
				<text class="iconfont icon-gouwuche2"></text>
				<text class="shoppimg-tex">选课单</text>
			</view>
			<view class="add-btn active" v-if="info.isAdd">已添加选课单</view>
			<view class="add-btn" v-else @click="add">添加选课单</view>
		</view>

		<!-- 		加载提示 -->
		<view class="loading" v-if="showLoading">
			<text style="--i:1">加</text>
			<text style="--i:2">载</text>
			<text style="--i:3">中</text>
			<text style="--i:4">.</text>
			<text style="--i:5">.</text>
			<text style="--i:6">.</text>
		</view>

	</view>
</template>
<script>
	import {
		loaded,
		loading,
		toast,
		redirectTo,
		navigateTo
	} from '@/utils/index.js';
	import {
		img_PATH
	} from '@/config';
	import {
		queryCourseDetail,
		addToCart,
		getUserInfo
	} from '@/api/index.js'
	export default {
		data() {
			return {
				imgurl: img_PATH,
				CustomBar: this.CustomBar,
				gologin: false,
				showLoading: false,
				showNone: false,
				courseId: '',
				info: {
					scheduleList: []
				}
			};
		},
		computed: {

			paddingbottom() {
				const res = wx.getSystemInfoSync()
				const {
					screenHeight,
					safeArea: {
						bottom
					}
				} = res
				if (screenHeight && bottom) {
					let safeBottom = screenHeight - bottom
					return safeBottom
				} else {
					return 0
				}
			}
		},
		components: {

		},
		onLoad(options) {
			this.courseId = options.courseId
			this.init()
		},
		onShow() {
			this.isLogin()
		},
		created() {

		},
		// 触底的事件
		onReachBottom() {

		},
		methods: {
			// 判断是否登录
			async isLogin() {
				let _res = await getUserInfo();
				if (_res.code == 200) {
					this.gologin = false
				}
				if (_res.code == 503) {
					this.gologin = true
				}
			},

			// 详情
			async init() {
				this.showLoading = true
				let _data = await queryCourseDetail(this.courseId);
				if (_data.code == 200) {
					this.showLoading = false
					this.info = _data.data
				}
			},
			// 添加选课单
			async add() {
				if (this.gologin) {
					toast('请登录')
					setTimeout(() => {
						navigateTo('/pages/index/login')
					}, 1500)
					return
				}
				let _data = await addToCart(this.courseId);
				toast(_data.msg)
				if (_data.code == 200) {
					this.showLoading = false
					this.info.isAdd = true
				}
			},

			to(path) {
				if (this.gologin) {
					toast('请登录')
					setTimeout(() => {
						navigateTo('/pages/index/login')
					}, 1500)
					return
				}
				redirectTo(path)
			},
		},

	}
</script>

